entries[111812] = { ["name"] = "Alchemielabor, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Alchemielabor bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
entries[111813] = { ["name"] = "Schmiede, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Schmiede bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Schmiedekunst und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Schmiedekunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Schmiedemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
