entries[111816] = { ["name"] = "Maßschneiderei, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Maßschneiderei bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Schneidereierzeugnissen und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Schneiderei', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Schneidereimissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
entries[111817] = { ["name"] = "Verzauberungsatelier, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Verzauberungsatelier bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
entries[111818] = { ["name"] = "Gerberei, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Gerberei bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Lederverarbeitung und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Lederverarbeitung', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Lederverarbeitungsmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
entries[111820] = { ["name"] = "Wechselblaster", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Tauscht Eure Position mit der eines anderen Gruppenmitglieds. Kann nicht im Kampf genutzt werden. (1 Min Abklingzeit)\n\"Achtung: Der Tausch mit einem Ziel, das einen neuralen Stummschalter verwendet, ist lebensgefährlich.\"\nVerkaufspreis:" }
entries[111821] = { ["name"] = "Blingtron 5000", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den verbesserten Blingtron 5000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)" }
entries[111842] = { ["name"] = "Sternwurzelknolle", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt 32 Gesundheit wieder her und verringert 10 Sek. lang den erlittenen Schaden um 40%. Kann nur in Ashran verwendet werden. (3 Min Abklingzeit)" }
