entries[111921] = { ["name"] = "Ingenieurskunst von Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lernt die Geheimnisse der Ingenieurskunst von Draenor und einige Rezepte kennen.\nBenötigt Ingenieurskunst (1)" }
entries[111922] = { ["name"] = "Verzauberkunst von Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lernt die Geheimnisse der Verzauberkunst von Draenor und einige Rezepte kennen.\nBenötigt Verzauberkunst (1)\n\"Eine Einführung in die Geheimnisse der draenischen Verzauberkunst.\"" }
entries[111923] = { ["name"] = "Inschriftenkunde von Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Inschriftenkunde von Draenor aus und lehrt Euch einige Rezepte.\nBenötigt Inschriftenkunde (1)\n\"Eine Einführung in die Geheimnisse der draenischen Inschriftenkunde\"" }
entries[111924] = { ["name"] = "Gnomische Werkstatt, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine gnomische Werkstatt bauen könnt.\n\nLevel 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\nLevel 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\nLevel 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nVerkaufspreis:" }
entries[111926] = { ["name"] = "Kodex des Aufstiegs", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Priester\nBenutzen: Lehrt Euch den Zauber 'Aufstieg'. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden." }
entries[111927] = { ["name"] = "Angelhütte, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Angelhütte in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht es Euch, in den Gewässern der Garnison kleine draenische Fische zu fangen. Gewährt außerdem Zugriff auf tägliche Angelquests.\n\nLevel 2\nErmöglicht es Euch, mittelgroße draenische Fische in den Gewässern der Garnison zu fangen.\n\nLevel 3\nErmöglicht es Euch, riesige draenische Fische in den Gewässern der Garnison fangen. Gewährt zusätzlich eine Chance, einen einzigartigen Fisch zu fangen, der dazu verwendet werden kann, mysteriöse Kreaturen an Land zu locken.\nBenötigt Angelhütte\nVerkaufspreis:" }
entries[111928] = { ["name"] = "Angelhütte, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Angelhütte in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht es Euch, in den Gewässern der Garnison kleine draenische Fische zu fangen. Gewährt außerdem Zugriff auf tägliche Angelquests.\n\nLevel 2\nErmöglicht es Euch, mittelgroße draenische Fische in den Gewässern der Garnison zu fangen.\n\nLevel 3\nErmöglicht es Euch, riesige draenische Fische in den Gewässern der Garnison fangen. Gewährt zusätzlich eine Chance, einen einzigartigen Fisch zu fangen, der dazu verwendet werden kann, mysteriöse Kreaturen an Land zu locken.\nBenötigt den Erfolg \"Draenorangler\".\nVerkaufspreis:" }
entries[111929] = { ["name"] = "Alchemielabor, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Alchemielabor auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:" }
entries[111930] = { ["name"] = "Alchemielabor, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Alchemielabor auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:" }
