entries[111955] = { ["name"] = "Skogs Tuch", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+2 Stärke\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nVerkaufspreis:" }
entries[111956] = { ["name"] = "Kaserne, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Kaserne bauen könnt." }
entries[111957] = { ["name"] = "Wiederverwertung, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Wiederverwertung bauen könnt.\n\nLevel 1\nErmöglicht, bei Missionen gelegentlich Bergungsgut zu finden.\n\nLevel 2\nErhöht die Wahrscheinlichkeit, bei Missionen Bergungsgut zu finden. Zusätzlich besteht jetzt die Chance, dass sich im Bergungsgut auch Gegenstände für Eure Anhänger befinden.\n\nLevel 3\nErhöht drastisch die Wahrscheinlichkeit, dass bei Missionen Bergungsgut gefunden wird.\nVerkaufspreis:" }
entries[111958] = { ["name"] = "Lagerhaus, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Lagerhaus bauen könnt.\n\nLevel 1\nErmöglicht Euch Zugang zu Eurer persönlichen Bank und erhöht die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 5.\n\nLevel 2\nErmöglicht Euch Zugang zu Eurer Gildenbank.\n\nLevel 3\nErmöglicht Euch Zugriff auf einen astralen Händler, der Transmogrifikations- und Leerenlagerdienste anbietet. Erhöht außerdem die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 15.\nVerkaufspreis:" }
entries[111959] = { ["name"] = "Scheune, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Scheune bauen könnt.\n\nLevel 1\nErmöglicht es Euch Grollhufe, Elekks, Wölfe und Talbuks zu fangen, um Leder und Pelze zu gewinnen. die in Rezepten für Lederverarbeitung und Schneiderei benötigt werden.\n\nLevel 2\nErlaubt es Euch, Eber und Flussbestien fangen, deren seltenes Fleisch zur stärksten Nahrung verarbeitet werden kann.\n\nLevel 3\nErmöglicht es Euch, Elitetiere zu fangen, um Wildblut zu erhalten, das für alle hergestellten epischen Rüstungen und Waffen verwendet wird.\nVerkaufspreis:" }
entries[111960] = { ["name"] = "Mondsturzgasthaus, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Mondsturzgasthaus bauen könnt.\n\nLevel 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\nLevel 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\nLevel 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nVerkaufspreis:" }
entries[111961] = { ["name"] = "Sägewerk, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt die erforderlichen Pläne zur Errichtung eines Sägewerkes.\n\nDieses Gebäude generiert eine tägliche Lieferung von Garnisonsmaterialien.\n\nLevel 1\nErmöglicht Euch, kleine Bäume in Draenor zu markieren, die gefällt werden sollen. Das so gewonnene Holz kann in Arbeitsaufträge für Garnisonsvorräte umgewandelt werden.\n\nLevel 2\nErmöglicht, mittelgroße Bäume zu markieren, um zusätzliches Holz zu gewinnen.\n\nLevel 3\nMit dem Sägewerk können größere Bäume markiert werden, was die Holzproduktion steigert.\nVerkaufspreis:" }
entries[111962] = { ["name"] = "Heiligtum des Gladiators, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Heiligtum des Gladiators bauen könnt.\n\nLevel 1\nErhöht Eure Erholung in den Außengebieten von Draenor, wenn Ihr Euch nicht im Kampf befindet, und ermöglicht das Sammeln gebrochener Knochen von gegnerischen Spielercharakteren, die Ihr besiegt habt (benötigt für Tribut des Eroberers).\n\nLevel 2\nErmöglicht sicheres Fallen und Unterwasseratmung in Außengebieten von Draenor. Ermöglicht außerdem Nemesisquests, für die Ihr gegnerische Spielercharaktere aus bestimmten Völkern besiegen müsst.\n\nLevel 3\nWenn Ihr über weniger als 35% Gesundheit verfügt, wird sämtlicher erlittene Schaden in Außengebieten von Draenor um 50% verringert. Gewährt außerdem Zugang zum Gladiatorenturnier im Kolosseum von Hochfels.\nVerkaufspreis:" }
entries[111963] = { ["name"] = "Handelsposten, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Handelsposten bauen könnt.\n\nLevel 1\nJeden Tag kommt ein Händler vorbei, bei dem Ihr Handwerkswaren kaufen könnt. Ermöglicht, Handwerksmaterialien gegen Garnisonsressourcen einzutauschen.\n\nLevel 2\nGewährt Zugang zur Fraktion Sha'tarverteidigung (Allianz) oder Lachender Schädel (Horde). Schaltet außerdem ein Auktionskonstrukt frei, das jedoch erst mit speziellen Teilen aus ganz Draenor repariert werden muss.\n\nLevel 3\nErhöht den Rufzuwachs in Draenor um 20%.\nVerkaufspreis:" }
entries[111964] = { ["name"] = "Zwergenbunker, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Zwergenbunker bauen könnt.\n\nLevel 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\nLevel 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\nLevel 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nVerkaufspreis:" }
entries[111965] = { ["name"] = "Magierturm, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Magierturm bauen könnt.\n\nLevel 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\nLevel 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\nLevel 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nVerkaufspreis:" }
entries[111966] = { ["name"] = "Zwergenbunker, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euren Zwergenbunker auf Stufe 2 ausbauen könnt.\n\nLevel 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\nLevel 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\nLevel 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[111967] = { ["name"] = "Zwergenbunker, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euren Zwergenbunker auf Stufe 3 ausbauen könnt.\n\nLevel 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\nLevel 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\nLevel 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nBenötigt den Erfolg \"Die Reihen füllen\".\nVerkaufspreis:" }
