entries[111969] = { ["name"] = "Scheune, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Scheune in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht es Euch Grollhufe, Elekks, Wölfe und Talbuks zu fangen, um Leder und Pelze zu gewinnen. die in Rezepten für Lederverarbeitung und Schneiderei benötigt werden.\n\nLevel 2\nErlaubt es Euch, Eber und Flussbestien fangen, deren seltenes Fleisch zur stärksten Nahrung verarbeitet werden kann.\n\nLevel 3\nErmöglicht es Euch, Elitetiere zu fangen, um Wildblut zu erhalten, das für alle hergestellten epischen Rüstungen und Waffen verwendet wird.\nBenötigt den Erfolg \"Meisterfallensteller\".\nVerkaufspreis:" }
entries[111970] = { ["name"] = "Kaserne, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Kaserne in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nSchaltet Patrouillenmissionen frei. Patrouillenmissionen erzielen einen erhöhten Erfahrungsbonus für Anhänger.\n\nLevel 2\nGestattet es einem Eurer Anhänger mit der Eigenschaft 'Leibwächter', Euch in Gebieten auf Draenor zu begleitet.\n\nLevel 3\nErhöht die maximale Anzahl an Anhängern um 5 und gewährt Zugriff auf Wachen und Banner spezifischer Völker.\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[111971] = { ["name"] = "Kaserne, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Kaserne in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nSchaltet Patrouillenmissionen frei. Patrouillenmissionen erzielen einen erhöhten Erfahrungsbonus für Anhänger.\n\nLevel 2\nGestattet es einem Eurer Anhänger mit der Eigenschaft 'Leibwächter', Euch in Gebieten auf Draenor zu begleitet.\n\nLevel 3\nErhöht die maximale Anzahl an Anhängern um 5 und gewährt Zugriff auf Wachen und Banner spezifischer Völker.\nBenötigt den Erfolg \"Patrouillen in Draenor\".\nVerkaufspreis:" }
entries[111972] = { ["name"] = "Verzauberungsatelier, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr das Verzauberungsatelier in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:" }
