entries[111984] = { ["name"] = "Gnomische Werkstatt, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure gnomische Werkstatt auf Stufe 2 ausbauen könnt.\n\nLevel 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\nLevel 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\nLevel 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[111985] = { ["name"] = "Gnomische Werkstatt, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure gnomische Werkstatt auf Stufe 3 ausbauen könnt.\n\nLevel 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\nLevel 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\nLevel 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nBenötigt den Erfolg \"Tödliche Technik\".\nVerkaufspreis:" }
entries[111986] = { ["name"] = "Handelsposten, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Handelsposten in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nJeden Tag kommt ein Händler vorbei, bei dem Ihr Handwerkswaren kaufen könnt. Ermöglicht, Handwerksmaterialien gegen Garnisonsressourcen einzutauschen.\n\nLevel 2\nGewährt Zugang zur Fraktion Sha'tarverteidigung (Allianz) oder Lachender Schädel (Horde). Schaltet außerdem ein Auktionskonstrukt frei, das jedoch erst mit speziellen Teilen aus ganz Draenor repariert werden muss.\n\nLevel 3\nErhöht den Rufzuwachs in Draenor um 20%.\nBenötigt den Abschluss der Außenpostenquests in den Spitzen von Arak oder Stufe 30.\nVerkaufspreis:" }
entries[111987] = { ["name"] = "Handelsposten, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Handelsposten in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nJeden Tag kommt ein Händler vorbei, bei dem Ihr Handwerkswaren kaufen könnt. Ermöglicht, Handwerksmaterialien gegen Garnisonsressourcen einzutauschen.\n\nLevel 2\nGewährt Zugang zur Fraktion Sha'tarverteidigung (Allianz) oder Lachender Schädel (Horde). Schaltet außerdem ein Auktionskonstrukt frei, das jedoch erst mit speziellen Teilen aus ganz Draenor repariert werden muss.\n\nLevel 3\nErhöht den Rufzuwachs in Draenor um 20%.\nBenötigt den Erfolg \"Wilde Freunde\".\nVerkaufspreis:" }
entries[111988] = { ["name"] = "Gerberei, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Gerberei in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Lederverarbeitung und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Lederverarbeitung', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Lederverarbeitungsmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:" }
