entries[111993] = { ["name"] = "Maßschneiderei, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Maßschneiderei auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Schneidereierzeugnissen und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Schneiderei', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Schneidereimissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:" }
entries[111996] = { ["name"] = "Mondsturzausgrabung, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Mondsturzausgrabung auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\nLevel 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Sammler draenischer Steine\".\nVerkaufspreis:" }
entries[111997] = { ["name"] = "Kräutergarten, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Kräutergarten in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nLässt täglich aus draenischen Samen Kräuter heranwachsen und macht Kräuter im Garten verfügbar.\n\nLevel 2\nErmöglicht es Anhängern mit der Eigenschaft 'Kräuterkunde', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Erhöht außerdem die Menge an Kräutern, die im Garten geerntet werden können und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nPflanzt einen einzigartigen Draenorobstbaum in Eurem Garten, der Nahrungsstärkungseffekte gewährt. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Sammler draenischer Samenkörner\".\nVerkaufspreis:" }
entries[111998] = { ["name"] = "Menagerie, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Menagerie in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nLockt Elitehaustiere an, mit denen Ihr kämpfen könnt, um Belohnungen zu erhalten. Ermöglicht es Euch, 5 Eurer Kampfhaustiere in Eurer Garnison unterzubringen.\n\nLevel 2\nErhöht die Erfolgschance Eurer Haustierfallen und verringert die Abklingzeit für das Wiederbeleben von Kampfhaustieren in Draenor. Ermöglicht es Euch außerdem, bis zu 10 Haustiere in Eurer Garnison unterzubringen.\n\nLevel 3\nSchaltet täglich einen Haustierkampf mit einzigartigen Belohnungen frei.\nBenötigt Haustiermenagerie\nVerkaufspreis:" }
entries[111999] = { ["name"] = "Menagerie, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Menagerie in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nLockt Elitehaustiere an, mit denen Ihr kämpfen könnt, um Belohnungen zu erhalten. Ermöglicht es Euch, 5 Eurer Kampfhaustiere in Eurer Garnison unterzubringen.\n\nLevel 2\nErhöht die Erfolgschance Eurer Haustierfallen und verringert die Abklingzeit für das Wiederbeleben von Kampfhaustieren in Draenor. Ermöglicht es Euch außerdem, bis zu 10 Haustiere in Eurer Garnison unterzubringen.\n\nLevel 3\nSchaltet täglich einen Haustierkampf mit einzigartigen Belohnungen frei.\nBenötigt den Erfolg \"Draenischer Haustierkämpfer\".\nVerkaufspreis:" }
entries[112001] = { ["name"] = "Stall, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Stall errichten könnt.\n\nLevel 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\nLevel 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\nLevel 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%.\nVerkaufspreis:" }
entries[112002] = { ["name"] = "Stall, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Stall in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\nLevel 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\nLevel 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%.\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[112003] = { ["name"] = "Stall, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Stall in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\nLevel 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\nLevel 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%.\nBenötigt den Erfolg \"Meister der Reittiere\".\nVerkaufspreis:" }
entries[112005] = { ["name"] = "Buchband des Gefängniswärters", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Paladin\nBenutzen: Lehrt Euch den Zauber 'Urteil des Gefängniswärters'. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden." }
entries[112006] = { ["name"] = "\"Zahnstocher\" der Gordunni", ["text"] = "Questgegenstand\n\"Die Klinge ist über und über mit Schmutz bedeckt.\"" }
entries[112015] = { ["name"] = "Verlassenengehirn", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Immer noch warm und pulsierend.\"" }
entries[112020] = { ["name"] = "Garnisonsbaupläne", ["text"] = "Questgegenstand\n\"Da ist zwar ein Loch in der Mitte, doch sie sind immer noch intakt.\"" }
entries[112022] = { ["name"] = "Rezept: Mächtiger Schattenschutztrank", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines mächtigen Schattenschutztranks.\nBenötigt Alchemie\n(400)\nBenötigt Alchemischer Katalysator - Lotus\nVerkaufspreis:\nMächtiger Schattenschutztrank\nBenutzen: Absorbiert 1134 Schattenschaden. Hält 2 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallisiertes Leben (2), Kristallphiole" }
entries[112023] = { ["name"] = "Rezept: Draenischer Stein der Weisen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Steins der Weisen.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Stein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 4.\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Echteisenerz" }
entries[112024] = { ["name"] = "Rezept: Draenisches Fläschchen der Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Beweglichkeit.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenisches Fläschchen der Beweglichkeit\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Feuerwurz (4), Sternenblume (4)" }
entries[112025] = { ["name"] = "Rezept: Draenorfläschchen des Tempos", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Draenorfläschchens des Tempos.\nBenötigt Alchemie\n(1)\nVerkaufspreis:\n[UNUSED]\nBenutzen: Erhöht das Tempo 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator , Magisches Wasser , Frostwurz (5)" }
entries[112026] = { ["name"] = "Rezept: Draenisches Fläschchen der Intelligenz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Intelligenz.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenisches Fläschchen der Intelligenz\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Sternenblume (4), Taladororchidee (4)" }
entries[112027] = { ["name"] = "Rezept: Draenisches Fläschchen der Stärke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Stärke.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenisches Fläschchen der Stärke\nBenutzen: Erhöht die Stärke 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Nagrandpfeilkelch (4), Gorgrondfliegenfalle (4)" }
entries[112030] = { ["name"] = "Rezept: Draenisches Fläschchen der Ausdauer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Ausdauer.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenisches Fläschchen der Ausdauer\nBenutzen: Erhöht die Ausdauer 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Taladororchidee (4), Nagrandpfeilkelch (4)" }
entries[112031] = { ["name"] = "Rezept: Großes draenisches Fläschchen der Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Beweglichkeit.\nBenötigt Alchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Beweglichkeit erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Beweglichkeit\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Wasser , Draenisches Fläschchen der Beweglichkeit (5)" }
entries[112032] = { ["name"] = "Rezept: Großes Draenorfläschchen des Tempos", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines großen Draenorfläschchens des Tempos.\nBenötigt Alchemie\n(1)\nVerkaufspreis:\n[UNUSED]\nBenutzen: Erhöht das Tempo 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator , Magisches Feuer , [Tyrannical Gladiator's Medallion of Meditation] , Schattentau" }
entries[112033] = { ["name"] = "Rezept: Großes draenisches Fläschchen der Intelligenz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Intelligenz.\nBenötigt Alchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Intelligenz erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Intelligenz\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Feuer , Draenisches Fläschchen der Intelligenz (5)" }
entries[112034] = { ["name"] = "Rezept: Großes draenisches Fläschchen der Stärke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Stärke.\nBenötigt Alchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Stärke erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Stärke\nBenutzen: Erhöht die Stärke 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Feuer , Draenisches Fläschchen der Stärke (5)" }
entries[112037] = { ["name"] = "Rezept: Großes draenisches Fläschchen der Ausdauer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Ausdauer.\nBenötigt Alchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Ausdauer erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Ausdauer\nBenutzen: Erhöht die Ausdauer 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Wasser , Draenisches Fläschchen der Ausdauer (5)" }
entries[112038] = { ["name"] = "Rezept: Draenischer Trank der Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Beweglichkeit.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Trank der Beweglichkeit\nBenutzen: Erhöht Eure Beweglichkeit 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Feuerwurz (3)" }
entries[112039] = { ["name"] = "Rezept: Draenischer Trank der Intelligenz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Intelligenz.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Trank der Intelligenz\nBenutzen: Erhöht Eure Intelligenz 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Taladororchidee (3)" }
entries[112040] = { ["name"] = "Rezept: Draenischer Trank der Stärke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Stärke.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Trank der Stärke\nBenutzen: Erhöht Eure Stärke 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Nagrandpfeilkelch (3)" }
entries[112041] = { ["name"] = "Rezept: Draenischer Trank der Rüstung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Rüstung.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Trank der Vielseitigkeit\nBenutzen: Erhöht Eure Vielseitigkeit 25 Sek. lang um 31 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Frostwurz (3)" }
entries[112042] = { ["name"] = "Rezept: Draenischer Trank der Manakanalisierung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Manakanalisierung.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Trank der Manakanalisierung\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 255 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Sternenblume (3)" }
entries[112043] = { ["name"] = "Rezept: Draenischer Manatrank", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Manatranks.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Manatrank\nBenutzen: Stellt 1700 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Gorgrondfliegenfalle (3)" }
entries[112045] = { ["name"] = "Rezept: Draenischer Trank der Verjüngung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Verjüngung.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nDraenischer Trank der Verjüngung\nBenutzen: Stellt 3400 Gesundheit und 850 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Heiltonikum , Draenischer Manatrank" }
entries[112047] = { ["name"] = "Rezept: Transmorphische Tinktur", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer transmorphischen Tinktur.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nTransmorphische Tinktur\nBenutzen: Vertauscht für kurze Zeit das Geschlecht des Anwenders.\nVerkaufspreis:\nBenötigt Sichelöl , Frostwurz (5)" }
entries[112049] = { ["name"] = "Rezept: Alchemischer Katalysator - Feuerwurz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, mit Feuerwurz einen Alchemistenkessel herzustellen.\nLiefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:" }
entries[112050] = { ["name"] = "Rezept: Alchemischer Katalysator - Fliegenfalle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, mit Gorgrondfliegenfallen einen Alchemistenkessel herzustellen.\nLiefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:" }
entries[112051] = { ["name"] = "Rezept: Alchemischer Katalysator - Sternenblume", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, mit Sternenblumen einen Alchemistenkessel herzustellen.\nLiefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:" }
entries[112052] = { ["name"] = "Rezept: Alchemischer Katalysator - Pfeilkelch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, mit Pfeilkelchen einen Alchemistenkessel herzustellen.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nAlchemischer Katalysator\nHandwerksmaterial\n\"Beschleunigt Reaktionen, die sonst Tausende von Jahren benötigen würden, und ist daher unerlässlich für die Alchemie auf Draenor.\"\nBenötigt Urgeist , Feuerwurz (2), Gorgrondfliegenfalle (2), Nagrandpfeilkelch (2), Sternenblume (2), Taladororchidee (2)" }
entries[112053] = { ["name"] = "Rezept: Alchemischer Katalysator - Orchidee", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, mit Taladororchideen einen Alchemistenkessel herzustellen.\nLiefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:" }
entries[112054] = { ["name"] = "Rezept: Alchemischer Katalysator - Lotus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, mit Chamäleonlotus einen Alchemistenkessel herzustellen.\nLiefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:" }
entries[112057] = { ["name"] = "Lebensechter mechanischer Frosteber", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren lebensechten mechanischen Eber beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[112059] = { ["name"] = "Wurmlochzentrifuge", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erschafft ein rotierendes Wurmloch, das der Ingenieur verwenden kann, um Draenor zu bereisen. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:" }
entries[112066] = { ["name"] = "Froststampfs Sorgen", ["text"] = "Wird beim Aufheben gebunden\nHals\n+2 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:" }
entries[112077] = { ["name"] = "Grutushs fellbesetzte Pantalons", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n10 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[112078] = { ["name"] = "Jehils Kletterstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 65 / 65\nVerkaufspreis:" }
entries[112082] = { ["name"] = "Lebendige Flamme", ["text"] = "Questgegenstand\n\"Ein Partikel reiner und lebendiger Flamme.\"" }
entries[112083] = { ["name"] = "Lebendiges Wasser", ["text"] = "Questgegenstand\n\"Ein Partikel reinen und lebendigen Wassers.\"" }
entries[112084] = { ["name"] = "Lebendige Erde", ["text"] = "Questgegenstand\n\"Ein Partikel reiner und lebendiger Erde.\"" }
entries[112085] = { ["name"] = "Lebendiger Wind", ["text"] = "Questgegenstand\n\"Ein Partikel reinen und lebendigen Windes.\"" }
entries[112086] = { ["name"] = "Windzerschlissene Schulterstücke", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[112087] = { ["name"] = "Obsidianpetroglyphe der Frostwölfe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erlangt Weisheit von dieser uralten Inschrift." }
entries[112088] = { ["name"] = "Runenperlen der Gordunni", ["text"] = "Questgegenstand\n\"Verstärkt die magische Macht von Fürst Morkurks Dienern.\"" }
entries[112089] = { ["name"] = "Glutblüte", ["text"] = "Questgegenstand" }
entries[112090] = { ["name"] = "Transmorphische Tinktur", ["text"] = "Benutzen: Vertauscht für kurze Zeit das Geschlecht des Anwenders.\nVerkaufspreis:" }
entries[112091] = { ["name"] = "Rauchgranate", ["text"] = "Questgegenstand\nBenutzen: Schleudert eine Rauchgranate auf einen Felswerfer der Gordunni, um ihn für die Zerstörung zu markieren. (5 Sek. Abklingzeit)" }
entries[112093] = { ["name"] = "Waffe - Mal der Zerschmetterten Hand", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass sie Gegner manchmal bluten lässt und ihnen 75 Schaden sowie im Verlauf von 6 Sek. zusätzlich 225 Schaden zufügt.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[112094] = { ["name"] = "Blutsuchers blutbespritzte Gewandung", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 3.\n+ 5 Vielseitigkeit\nHaltbarkeit 140 / 140\nVerkaufspreis:" }
entries[112095] = { ["name"] = "Halb aufgegessene Banane", ["text"] = "Benutzen: Stellt im Verlauf von 21 Sek. ( 38 * 21 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Offensichtlich ohne Schale.\"\nVerkaufspreis:" }
entries[112096] = { ["name"] = "Verbeulte Schädelkappe eines Ogers", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n8 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[112099] = { ["name"] = "Erhebliches Elixier der Schatten", ["text"] = "Questgegenstand\nBenutzen: In der Nähe von Zelleks Hütte im Akrazversteck trinken, um das Schattenreich zu betreten.\n\"Die Substanz im Innern ist zäh und schwarz wie Teer.\"" }
entries[112100] = { ["name"] = "Elixier der Schatten", ["text"] = "Questgegenstand\nBenutzen: Bei Ishaals Hütte in der Schattenlichtung trinken, um in das Schattenreich blicken zu können." }
entries[112101] = { ["name"] = "Ishaals Kugel", ["text"] = "Questgegenstand\n\"Dunkle Wolken wirbeln unter der Oberfläche.\"" }
entries[112107] = { ["name"] = "Mysteriöses Ei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 3 tagen (Realzeit)\n\"Aus diesem Ei schlüpft etwas.\"\nVerkaufspreis:" }
entries[112108] = { ["name"] = "Zerbrochene Eierschale", ["text"] = "Wird beim Aufheben gebunden\n\"Aus diesem Ei ist etwas geschlüpft!\"\n<Zum Öffnen rechtsklicken>" }
entries[112110] = { ["name"] = "Panzerschild des Verschlingers", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n48 Rüstung\n+2 Stärke\n+7 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 2 Vielseitigkeit\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[112111] = { ["name"] = "Bauschutt", ["text"] = "\"In den Gewässern Eurer Garnison leben noch keine Fische...\"\nVerkaufspreis:" }
entries[112113] = { ["name"] = "Pandarenfell", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Gäbe einen hervorragenden Teppich für die Eingangshalle ab.\"" }
entries[112115] = { ["name"] = "Waffe - Mal des Schattenmonds", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal die Vielseitigkeit 15 Sek. lang um 77 erhöht wird.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[112119] = { ["name"] = "Worgenschnauze", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Dieses Ding wird keine nervtötenden Geräusche mehr von sich geben.\"" }
entries[112120] = { ["name"] = "Trollfüße", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"So, wie die stinken, können damit alle Arten von Tieren ferngehalten werden.\"" }
entries[112121] = { ["name"] = "Draeneischwanz", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Fein zermahlen ergibt er eine mächtige nekromantische Zutat.\"" }
entries[112122] = { ["name"] = "Orczahn", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Gibt eine hervorragende Speerspitze ab.\"" }
entries[112123] = { ["name"] = "Taurenhuf", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Die Geheimzutat der Konditoren.\"" }
entries[112124] = { ["name"] = "Abgeschlagener Nachtelfenkopf", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Die perfekte Winterhauchbaumspitze.\"" }
entries[112125] = { ["name"] = "Goblinzinken", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Die größeren Nasen stammen von den ältesten Goblins.\"" }
entries[112126] = { ["name"] = "Zwergenrückgrat", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Kurz, aber kräftig.\"" }
entries[112127] = { ["name"] = "Ein Büschel Gnomhaar", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Ideal für Blutelfenperücken.\"" }
entries[112128] = { ["name"] = "Blutelfenohr", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Eignet sich hervorragend, um sich als Elf auszugeben.\"" }
entries[112131] = { ["name"] = "Menschliche Knochensplitter", ["text"] = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n\"Eignet sich gut für modischen Orcschmuck.\"" }
entries[112135] = { ["name"] = "Ei eines Schreckensraben", ["text"] = "Questgegenstand\n\"Ihr hört ein leises Picken in seinem Innern.\"" }
entries[112142] = { ["name"] = "Weltenbrecherpläne", ["text"] = "Questgegenstand\n\"Enthält keine Bilder.\"" }
entries[112146] = { ["name"] = "Weltenbrecherpläne, S. 37-51", ["text"] = "Questgegenstand\n\"Mehrere Seiten wurden vollgekritzelt.\"" }
entries[112147] = { ["name"] = "Weltenbrecherpläne, S. 58-70", ["text"] = "Questgegenstand\n\"Enthält offenbar keinen Abschnitt über Sicherheitsmaßnahmen.\"" }
entries[112148] = { ["name"] = "Weltenbrecherpläne, S. 71-84", ["text"] = "Questgegenstand\n\"Enthält vor allem handschriftliche Notizen und grobe Diagramme.\"" }
entries[112149] = { ["name"] = "Stadtbrecherpläne", ["text"] = "Questgegenstand\n\"Größtenteils vollständig!\"" }
entries[112154] = { ["name"] = "Lehrbuch: Rückzug", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Jäger\nBenutzen: Halbiert die Abklingzeit Eurer Fähigkeit 'Rückzug'. Kann nur in Ashran eingesetzt werden." }
entries[112155] = { ["name"] = "Tiefseeschuppenfragment", ["text"] = "Benutzen: Setzt zehn Tiefseeschuppenfragmente zusammen, um eine vollständige Tiefseeschuppe zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112156] = { ["name"] = "Geschwärztes Drachenschuppenfragment", ["text"] = "Benutzen: Setzt zehn geschwärzte Drachenschuppenfragmente zusammen, um eine vollständige geschwärzte Drachenschuppe zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112157] = { ["name"] = "Prismatisches Schuppenfragment", ["text"] = "Benutzen: Setzt zehn Fragmente prismatischer Schuppen zusammen, um eine vollständige prismatische Schuppe zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112158] = { ["name"] = "Eisiges Drachenschuppenfragment", ["text"] = "Benutzen: Setzt zehn eisige Drachenschuppenfragmente zusammen, um eine vollständige eisige Drachenschuppe zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112160] = { ["name"] = "Waffe - Mal des Schwarzfels", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal die Vielseitigkeit 12 Sek. lang um 77 erhöht wird. Der Effekt kann nur auftreten, wenn Eure Gesundheit unter 60% liegt.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[112164] = { ["name"] = "Waffe - Mal des Kriegshymnenklans", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal das Tempo um ( 15 * 10) erhöht wird, bevor sich dieser Wert alle 2 Sek. um 10% verringert.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[112165] = { ["name"] = "Waffe - Mal des Frostwolfs", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal der kritische Trefferwert 6 Sek. lang um 77 erhöht wird. Der Effekt ist 2-mal stapelbar.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[112166] = { ["name"] = "Samedis Fetisch", ["text"] = "Questgegenstand\nBenutzen: Innerhalb von 5 Metern um einen der gefallenen Schattenjäger von Kajassa benutzen." }
entries[112177] = { ["name"] = "Nerubisches Chitinfragment", ["text"] = "Benutzen: Setzt zehn nerubische Chitinfragmente zusammen, um vollständiges nerubisches Chitin zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112178] = { ["name"] = "Jormungarschuppenfragment", ["text"] = "Benutzen: Setzt zehn Jormungarschuppenfragmente zusammen, um eine vollständige Jormungarschuppe zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112179] = { ["name"] = "Flicken aus dickem Grollhufleder", ["text"] = "Benutzen: Setzt zehn Flicken aus dickem Grollhufleder zusammen, um ein vollständiges Stück dickes Grollhufleder zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[112180] = { ["name"] = "Flicken aus kristalldurchströmten Leder", ["text"] = "Benutzen: Setzt zehn Flicken aus kristalldurchdrungenem Leder zusammen, um ein Stück kristalldurchdrungenes Leder zu erhalten.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kürschnerei ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
