entries[112186] = { ["name"] = "Fischlieferung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schaltet Zugriff auf die Spezialisierung Fischlieferung der Angelhütte in Eurer Garnison frei.\n\"Lehrt Euch, wie Ihr ein Gebäude in Eurer Garnison spezialisiert.\"" }
entries[112187] = { ["name"] = "Klippenspringerstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n7 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 7.\nHaltbarkeit 65 / 65\n\"Damit springt man so flink wie der Wind, der um die Klippen pfeift.\"\nVerkaufspreis:" }
entries[112195] = { ["name"] = "Schattenstaub", ["text"] = "Questgegenstand\n\"Dieser Staub hat eine besondere Verbindung mit dem Reich der Schatten. Er ist eine entscheidende Zutat für die heiligen Riten der Krallenpriester.\"" }
entries[112196] = { ["name"] = "Arkaner Nexus", ["text"] = "Questgegenstand\n\"Mächtiger Kristall, mit dem der Verlauf von Leylinien verändert wird.\"" }
entries[112199] = { ["name"] = "Schriftrollenfragment der Rabensprecher", ["text"] = "Questgegenstand\n\"Preist die vielen Tugenden der Schreckensraben und erläutert die Feinheiten der Glaubenssätze der Rabensprecher.\"" }
entries[112203] = { ["name"] = "Stadtbrecherpläne", ["text"] = "Questgegenstand\n\"Größtenteils vollständig!\"" }
entries[112204] = { ["name"] = "Pfote eines Erdbinders der Blutmähnen", ["text"] = "Questgegenstand\n\"Die Krallen sind stark abgenutzt, aber dennoch scharf.\"" }
entries[112206] = { ["name"] = "Talisman der unerfüllten Sehnsüchte", ["text"] = "Wird beim Aufheben gebunden\nHals\n+2 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Meisterschaftswertung um + 5.\nVerkaufspreis:" }
entries[112207] = { ["name"] = "Ritualmesser der Rabensprecher", ["text"] = "Questgegenstand\nBenutzen: Besorgt eine Pranke von einem toten Erdbinder der Blutmähnen im Blutmähnental. (3 Sek. Abklingzeit)" }
entries[112208] = { ["name"] = "Abgetrennte Pfote von Grimalkinde", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Die Pfote ist verdreht und missgestaltet, doch immer noch recht gefährlich.\"" }
entries[112209] = { ["name"] = "Abgetrennte Pfote von Rotauge", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Von Blut rot gefärbt. Ihr Vorbesitzer nahm nur sehr selten ein Bad.\"" }
