entries[112243] = { ["name"] = "Schlüssel für Ga'nars Fesseln", ["text"] = "Questgegenstand\n\"Aus Eisen gefertigt.\"" }
entries[112244] = { ["name"] = "Schriftrolle der Massenteleportation", ["text"] = "Questgegenstand\nBenutzen: Beschwört Garnisonsstreitkräfte, damit sie Euch im Kampf gegen den Hexenfürst Morkurk zur Seite stehen." }
entries[112261] = { ["name"] = "Vergessene Verteidigerklinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n4 - 8 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\n\"Die Jahrzehnte, die es den Elementen ausgesetzt war, haben ihre Spuren hinterlassen, doch es ist immer noch eine beeindruckende Waffe.\"\nVerkaufspreis:" }
entries[112263] = { ["name"] = "Yazheeras brennende Armschienen", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Kette\n6 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[112266] = { ["name"] = "Gefrorenes Pflanzenmaterial", ["text"] = "Questgegenstand\n\"Überraschend strapazierfähig und beinahe immun gegen Kälte und Wind.\"" }
entries[112270] = { ["name"] = "Dunkelmond-Karte von Draenor", ["text"] = "\"Irgendeine Dunkelmond-Karte von Draenor. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
