entries[112307] = { ["name"] = "Notfallraketenrucksack", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schnallt Euch Euren Raketenrucksack auf den Rücken und zündet ihn an, um durch die Luft zu fliegen. (10 Sek. Abklingzeit)" }
entries[112308] = { ["name"] = "Zorn der Schmiede", ["text"] = "Questgegenstand\n\"Morkeths wertvollste Schöpfung.\"" }
entries[112317] = { ["name"] = "Geflügeltes Stundenglas", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nSchmuck\n+3 Intelligenz\nAnlegen: Jedes Mal, wenn Eure Angriffe treffen, besteht eine Chance, dass Ihr 20 Sek. lang 51 Vielseitigkeit erhaltet. (15% Chance, 115 Sek. Abklingzeit) (Procchance: 15%, 1.917Min. Abklingzeit)\nVerkaufspreis:" }
entries[112318] = { ["name"] = "Schädel des Krieges", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nSchmuck\n+4 [Beweglichkeit oder Stärke]\nAnlegen: Jedes Mal, wenn Eure Angriffe treffen, besteht eine Chance, dass Ihr 20 Sek. lang 51 kritischen Trefferwert erhaltet. (15% Chance, 115 Sek. Abklingzeit) (Procchance: 15%, 1.917Min. Abklingzeit)\nVerkaufspreis:" }
