entries[112321] = { ["name"] = "Verzauberter Staub", ["text"] = "Benutzen: Lässt jemanden 5 Min. lang glänzend aussehen.\nVerkaufspreis:" }
entries[112322] = { ["name"] = "Kompliziertes Holz", ["text"] = "Wird beim Aufheben gebunden\n\"Das ist nicht so einfach.\"\nVerkaufspreis:" }
entries[112323] = { ["name"] = "Fass mit Schwarzfelspulver", ["text"] = "Questgegenstand\nEinzigartig\n\"Einmal geöffnet, wird dieses Fass hinter Euch stets eine Spur Schwarzfelspulver zurücklassen, bis Ihr wieder bei Thaelin seid.\"" }
entries[112324] = { ["name"] = "Alptraumhafter Anbindepfosten", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen alptraumhaften Anbindepfosten.\n\nGruppen- oder Schlachtzugsmitglieder können den Pfosten benutzen, um ihre Reittiere 20 Min. lang in kriegsgeschmiedete Nachtmahre zu verwandeln. (3 Min Abklingzeit)\nBenötigt Kriegsgeschmiedeter Nachtmahr" }
entries[112326] = { ["name"] = "Kriegsgeschmiedeter Nachtmahr", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren kriegsgeschmiedeten Nachtmahr oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Alptraumross aus gehärtetem Stahl und rachsüchtigem Geist. Dieser Gefährte wird Euch ohne zu zucken in die Feuerlande und zurück folgen.\"\nWoW-Shop" }
entries[112327] = { ["name"] = "Grinsender Häscher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren grinsenden Häscher oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Lächeln und ein Grinsen sind zwei verschiedene Dinge. Genau wie kochen und küssen.\"\nWoW-Shop" }
entries[112328] = { ["name"] = "Jungwurzel", ["text"] = "Questgegenstand\n\"Soll magische verjüngende Eigenschaften besitzen.\"" }
entries[112329] = { ["name"] = "Faragift", ["text"] = "Questgegenstand\n\"Ein lähmendes Gift.\"" }
entries[112331] = { ["name"] = "\"Tillik\" vom Schwarm", ["text"] = "Questgegenstand\nEinzigartig\n\"Es ist über und über mit Schleim und klebrigem Saft bedeckt. Das will keiner lange mit sich herumtragen.\"" }
entries[112332] = { ["name"] = "Gesammelte Kiesel", ["text"] = "Questgegenstand\nBenutzen: Verwendet diese Kieselsteine, um damit Schlummerblüten zum Platzen zu bringen." }
entries[112334] = { ["name"] = "Verderbtes Holz", ["text"] = "Questgegenstand\n\"Knorrig wie die teufelsverfluchte Essenz des Urtums, von dem es stammt. Hoffentlich wird es das Garnisonsgebäude, das Baros damit bauen will, nicht infizieren.\"" }
entries[112335] = { ["name"] = "Geronnenes Blut von Sethe", ["text"] = "Questgegenstand\n\"Sethes Todesfluch wird ewiglich in seinem Blut weiterleben.\"" }
entries[112336] = { ["name"] = "Windnatternflügel", ["text"] = "Questgegenstand\n\"Diese Flügel wurden Sethes Kindern entrissen und sollten einen würdigen Tribut für Anzu darstellen.\"" }
entries[112337] = { ["name"] = "Schwarzfelswaffe", ["text"] = "Questgegenstand\n\"Solide und aus schwerem Dunkeleisen gefertigt.\"" }
